import { useState, useEffect, useRef } from "react";
// Styles are loaded via src/index.js → src/styles/global.css


// ──────────────────────────────────────────────
// ICONS (inline SVG helpers)
// ──────────────────────────────────────────────
const Icon = ({ name, size = 20, style = {} }) => {
  const icons = {
    quran:    <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M4 19.5A2.5 2.5 0 0 0 6.5 22H20V2H6.5A2.5 2.5 0 0 0 4 4.5v15z"/>,
    hadith:   <><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></>,
    duas:     <path d="M18 8h1a4 4 0 0 1 0 8h-1M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8zM6 1v3M10 1v3M14 1v3"/>,
    pillars:  <><rect x="3" y="18" width="18" height="3" rx="1"/><rect x="7" y="7" width="3" height="11"/><rect x="14" y="7" width="3" height="11"/><path d="M12 2L3 7h18L12 2z"/></>,
    concepts: <path d="M12 2a7 7 0 0 1 7 7c0 2.38-1.19 4.47-3 5.74V17a1 1 0 0 1-1 1H9a1 1 0 0 1-1-1v-2.26C6.19 13.47 5 11.38 5 9a7 7 0 0 1 7-7zM9 21h6M10 17v4M14 17v4"/>,
    books:    <><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/><line x1="9" y1="7" x2="15" y2="7"/><line x1="9" y1="11" x2="15" y2="11"/></>,
    advanced: <><path d="M22 10v6M2 10l10-5 10 5-10 5-10-5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></>,
    audio:    <><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07"/></>,
    search:   <><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></>,
    moon:     <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>,
    sun:      <><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></>,
    globe:    <><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></>,
    arrow:    <><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></>,
    external: <><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 0 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></>,
  };
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
      style={style} aria-hidden="true">
      {icons[name] || null}
    </svg>
  );
};

// ──────────────────────────────────────────────
// DATA
// ──────────────────────────────────────────────
const TABS = [
  { id: "quran",    label: "Quran",          icon: "quran"    },
  { id: "hadith",   label: "Hadith",         icon: "hadith"   },
  { id: "duas",     label: "Duas",           icon: "duas"     },
  { id: "pillars",  label: "Pillars",        icon: "pillars"  },
  { id: "concepts", label: "Key Concepts",   icon: "concepts" },
  { id: "books",    label: "Books",          icon: "books"    },
  { id: "advanced", label: "Advanced",       icon: "advanced" },
  { id: "audio",    label: "Audio Lectures", icon: "audio"    },
];

const PILLARS = [
  { num: "١", icon: "☝️", name: "Shahada", arabic: "الشهادة", desc: "Declaration that there is no god but Allah and Muhammad ﷺ is His final messenger — the gateway into Islam." },
  { num: "٢", icon: "🕌", name: "Salah",   arabic: "الصلاة",  desc: "Five daily prayers at their prescribed times: Fajr, Dhuhr, Asr, Maghrib, and Isha." },
  { num: "٣", icon: "💚", name: "Zakat",   arabic: "الزكاة",  desc: "Obligatory annual charity (2.5% of savings) given to those in need, purifying one's wealth." },
  { num: "٤", icon: "🌙", name: "Sawm",    arabic: "الصوم",   desc: "Fasting the month of Ramadan from dawn to sunset — discipline, gratitude, and closeness to Allah." },
  { num: "٥", icon: "🕋", name: "Hajj",    arabic: "الحج",    desc: "Pilgrimage to Mecca once in a lifetime for those physically and financially able." },
];

const BOOKS = [
  {
    level: "Beginner", badge: "badge-green",
    title: "Kitaab at-Tawheed",
    author: "Muhammad ibn Abd al-Wahhab",
    desc: "The foundational book on Islamic monotheism. Essential for every Muslim to understand the core of their faith.",
    tags: ["Aqeedah", "Tawhid"], link: "https://kalamullah.com/Books/Kitaab%20At-Tawheed.pdf",
  },
  {
    level: "Beginner", badge: "badge-green",
    title: "Thalaathat al-Usool",
    author: "Muhammad ibn Abd al-Wahhab",
    desc: "The Three Fundamental Principles — a concise text on your Lord, your religion, and your Prophet ﷺ.",
    tags: ["Aqeedah", "Beginner"], link: "https://kalamullah.com",
  },
  {
    level: "Beginner", badge: "badge-green",
    title: "Ar-Raheeq al-Makhtum",
    author: "Saifur Rahman al-Mubarakpuri",
    desc: "The Sealed Nectar — the most famous biography of Prophet Muhammad ﷺ, winner of the World Muslim League prize.",
    tags: ["Sirah", "Biography"], link: "https://kalamullah.com/Books/The%20Sealed%20Nectar.pdf",
  },
  {
    level: "Intermediate", badge: "badge-gold",
    title: "Riyad as-Salihin",
    author: "Imam al-Nawawi",
    desc: "Gardens of the Righteous — a comprehensive Hadith compilation covering all aspects of daily Muslim life.",
    tags: ["Hadith", "Daily Life", "Sunnah"], link: "https://sunnah.com/riyadussalihin",
  },
  {
    level: "Advanced", badge: "badge-purple",
    title: "Ihya Ulum al-Din",
    author: "Imam al-Ghazali (d. 1111 CE)",
    desc: "The Revival of the Religious Sciences — 4-volume magnum opus on worship, ethics, and spiritual purification.",
    tags: ["Tazkiyah", "Fiqh", "Classic"], link: "https://emaanlibrary.com",
  },
  {
    level: "Advanced", badge: "badge-purple",
    title: "Madarij as-Salikin",
    author: "Ibn al-Qayyim al-Jawziyyah",
    desc: "Ranks of the Divine Seekers — Ibn al-Qayyim's profound commentary on the stations of the spiritual path.",
    tags: ["Tazkiyah", "Spirituality"], link: "https://kalamullah.com",
  },
  {
    level: "Advanced", badge: "badge-purple",
    title: "Tafsir Ibn Kathir",
    author: "Ibn Kathir (d. 1373 CE)",
    desc: "The most widely studied Quran commentary — clear, Hadith-based, and accessible for students of knowledge.",
    tags: ["Tafsir", "Quran"], link: "https://quran.com/tafsirs/en-tafisr-ibn-kathir",
  },
  {
    level: "Contemporary", badge: "badge-blue",
    title: "Don't Be Sad",
    author: "Aid al-Qarni",
    desc: "A practical and comforting guide to peace of mind and happiness grounded in Islamic teachings.",
    tags: ["Self-Help", "Contemporary"], link: "https://muslim-library.com",
  },
  {
    level: "Contemporary", badge: "badge-blue",
    title: "Reclaim Your Heart",
    author: "Yasmin Mogahed",
    desc: "Spiritual reflections on detachment, purpose, and finding fulfillment by connecting the heart to Allah.",
    tags: ["Spirituality", "Contemporary"], link: "https://muslimcentral.com",
  },
  {
    level: "Contemporary", badge: "badge-blue",
    title: "Purification of the Heart",
    author: "Hamza Yusuf",
    desc: "Translation and commentary on Imam Mawlud's Matharat al-Qulub — a guide to Islamic ethics and the diseases of the heart.",
    tags: ["Tazkiyah", "Ethics"], link: "https://emaanlibrary.com",
  },
];

const AUDIO_SOURCES = [
  { icon: "🎙️", name: "Muslim Central", desc: "Thousands of lectures from Nouman Ali Khan, Omar Suleiman, Mufti Menk, Yasir Qadhi, and 140+ speakers. The best organized Islamic audio library online.", link: "https://muslimcentral.com" },
  { icon: "📖", name: "Bayyinah.org", desc: "Deep Quranic reflections and Seerah by Nouman Ali Khan — including The Divine Reality and powerful Ramadan specials.", link: "https://bayyinah.org" },
  { icon: "🌿", name: "Yaqeen Institute", desc: "Dr. Omar Suleiman's series on faith, mental health, history, and contemporary issues — heart-touching and well-researched.", link: "https://yaqeeninstitute.org/audio" },
  { icon: "📚", name: "EmaanLibrary Audio", desc: "Over 10,000 authentic lectures by classical scholars — Ibn Qayyim, Albani, Bin Baz, Fawzan. Perfect for advanced students.", link: "https://emaanlibrary.com" },
  { icon: "🏛️", name: "AlMaghrib Institute", desc: "University-style intensive seminars with Yasir Qadhi, Waleed Basyouni, and top instructors. On-demand audio available.", link: "https://almaghrib.org" },
  { icon: "🎓", name: "Bakkah.net", desc: "Free full courses with audio recordings by Ustaadh Moosaa Richardson on Aqeedah, Fiqh, Hadith, and Arabic grammar.", link: "https://bakkah.net/en/free-islamic-courses-online-recordings-workbooks-resources.htm" },
];

const LIBRARIES = [
  { name: "EmaanLibrary.com", desc: "Best for advanced students — 1000s of free PDFs by classical and contemporary scholars.", link: "https://emaanlibrary.com" },
  { name: "Kalamullah.com",   desc: "Classic free library, famous for high-quality PDFs of Ibn Taymiyyah & Ibn al-Qayyim.", link: "https://kalamullah.com" },
  { name: "Muslim-Library.com", desc: "Comprehensive e-library in 100+ languages for global Muslim readers.", link: "https://muslim-library.com" },
  { name: "Archive.org/Islam", desc: "Internet Archive's Islamic collection — rare manuscripts, classical texts, and more.", link: "https://archive.org/details/islam" },
];

// ──────────────────────────────────────────────
// REUSABLE COMPONENTS
// ──────────────────────────────────────────────
const SectionHeading = ({ title, tag }) => (
  <div className="sec-heading">
    <h3>{title}</h3>
    <div className="sec-divider" />
    {tag && <span className="sec-tag">{tag}</span>}
  </div>
);

const CardLink = ({ href, label = "Visit →" }) => (
  <a href={href} target="_blank" rel="noopener noreferrer" className="card-link">
    {label} <Icon name="arrow" size={14} />
  </a>
);

const VerseBox = ({ arabic, translation, ref: refText }) => (
  <div className="verse-box">
    <div className="verse-arabic">{arabic}</div>
    <div className="verse-translation">{translation}</div>
    <div className="verse-ref">{refText}</div>
  </div>
);

// ──────────────────────────────────────────────
// PAGE COMPONENTS
// ──────────────────────────────────────────────
const QuranPage = () => (
  <div>
    <div className="page-header">
      <div className="bismillah">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</div>
      <h2>The Holy Quran</h2>
      <p>Explore the word of Allah — authentic Quranic resources with translations, tafsir, and recitations.</p>
    </div>

    <div className="stats-row">
      <div className="stat-card"><div className="stat-num">114</div><div className="stat-label">Surahs</div></div>
      <div className="stat-card"><div className="stat-num">6,236</div><div className="stat-label">Verses</div></div>
      <div className="stat-card"><div className="stat-num">77,430</div><div className="stat-label">Words</div></div>
      <div className="stat-card"><div className="stat-num">30</div><div className="stat-label">Juz</div></div>
    </div>

    <SectionHeading title="Featured Verses" tag="Quran" />
    <VerseBox arabic="إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ ۖ وَإِن تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا" translation="Indeed, Allah does not do injustice, even as much as an atom's weight; while if there is a good deed, He multiplies it and gives from Himself a great reward." ref="Surah An-Nisa (4:40)" />
    <VerseBox arabic="وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ" translation="And whoever fears Allah — He will make for him a way out, and will provide for him from where he does not expect." ref="Surah At-Talaq (65:2–3)" />

    <SectionHeading title="Quran Resources" tag="Trusted Sources" />
    <div className="grid">
      {[
        { icon: "📖", name: "Quran.com", desc: "Complete Quran with 50+ translations, tafsir, and recitations from leading scholars worldwide.", link: "https://quran.com", label: "Open Quran.com" },
        { icon: "🔎", name: "Al-Quran.info", desc: "Word-by-word Quran analysis with grammar, morphology, and deep linguistic tools for students.", link: "https://al-quran.info", label: "Open Al-Quran.info" },
        { icon: "🎧", name: "Quran Central", desc: "Listen to recitations from 200+ Qaris worldwide with synchronized Arabic text and translation.", link: "https://qurancentral.com", label: "Open Quran Central" },
        { icon: "🌐", name: "Tanzil.net", desc: "Multi-translation Quran navigator — compare scholars side-by-side with verse-level precision.", link: "https://tanzil.net", label: "Open Tanzil" },
        { icon: "✍️", name: "Quran Explorer", desc: "Interactive Quran with built-in audio playback, translation overlay, and personal bookmarks.", link: "https://quranexplorer.com", label: "Open QuranExplorer" },
        { icon: "📱", name: "iQuran (KSU)", desc: "Clean Quran reading experience from King Saud University with multiple translators.", link: "https://quran.ksu.edu.sa", label: "Open iQuran" },
      ].map(r => (
        <div className="card" key={r.name}>
          <div className="card-icon">{r.icon}</div>
          <h4>{r.name}</h4>
          <p>{r.desc}</p>
          <CardLink href={r.link} label={r.label + " →"} />
        </div>
      ))}
    </div>
  </div>
);

const HadithPage = () => (
  <div>
    <div className="page-header">
      <div className="bismillah">السُّنَّةُ النَّبَوِيَّة</div>
      <h2>Hadith Collections</h2>
      <p>The authenticated sayings and actions of Prophet Muhammad ﷺ — the second source of Islamic law.</p>
    </div>
    <div className="stats-row">
      <div className="stat-card"><div className="stat-num">7,563</div><div className="stat-label">Sahih Bukhari</div></div>
      <div className="stat-card"><div className="stat-num">5,362</div><div className="stat-label">Sahih Muslim</div></div>
      <div className="stat-card"><div className="stat-num">4,590</div><div className="stat-label">Sunan Abu Dawud</div></div>
      <div className="stat-card"><div className="stat-num">3,956</div><div className="stat-label">Jami' Tirmidhi</div></div>
    </div>
    <SectionHeading title="Featured Hadith" tag="Hadith" />
    <VerseBox arabic="الْمُؤْمِنُ الَّذِي يُخَالِطُ النَّاسَ وَيَصْبِرُ عَلَى أَذَاهُمْ خَيْرٌ مِنَ الَّذِي لاَ يُخَالِطُهُمْ" translation='"The believer who mixes with people and endures their harm is better than the one who does not mix with them nor endure their harm."' ref="Sunan Ibn Majah 4032 — Sahih" />
    <VerseBox arabic="إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى" translation='"Actions are but by intentions, and every person will have only what they intended."' ref="Sahih al-Bukhari 1 — The Opening Hadith" />
    <SectionHeading title="Hadith Resources" tag="Authenticated Sources" />
    <div className="grid">
      {[
        { icon: "📚", name: "Sunnah.com", desc: "The most comprehensive Hadith database online — Bukhari, Muslim, Abu Dawud, Tirmidhi, Nasai, Ibn Majah, and more.", link: "https://sunnah.com" },
