const BooksPage = ({ search }) => {
  const levels = ["Beginner", "Intermediate", "Advanced", "Contemporary"];
  const filtered = search
    ? BOOKS.filter(b => [b.title, b.author, b.level, ...b.tags].join(" ").toLowerCase().includes(search.toLowerCase()))
    : BOOKS;

  return (
    <div>
      <div className="page-header">
        <div className="bismillah">اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ</div>
        <h2>Islamic Books Library</h2>
        <p>"Read in the name of your Lord who created." — Quran 96:1 &nbsp;|&nbsp; Essential reading from classical and contemporary scholars.</p>
      </div>

      {filtered.length === 0 ? (
        <div className="no-results">
          <div className="big">📚</div>
          <p>No books found for "{search}"</p>
        </div>
      ) : (
        levels.map(level => {
          const books = filtered.filter(b => b.level === level);
          if (!books.length) return null;
          const tagMap = { Beginner: "badge-green", Intermediate: "badge-gold", Advanced: "badge-purple", Contemporary: "badge-blue" };
          return (
            <div key={level} style={{ marginBottom: 36 }}>
              <SectionHeading title={`${level} Books`} tag={level} />
              <div className="grid-2">
                {books.map(book => (
                  <div className="card" key={book.title}>
                    <span className={`badge ${tagMap[level]}`}>{book.level}</span>
                    <h4>{book.title}</h4>
                    <div className="book-author">by {book.author}</div>
                    <p>{book.desc}</p>
                    <div className="tags">{book.tags.map(t => <span className="tag" key={t}>{t}</span>)}</div>
                    <CardLink href={book.link} label="Get Book →" />
                  </div>
                ))}
              </div>
            </div>
          );
        })
      )}

      <div className="library-banner">
        <h3>🗂️ Free Digital Libraries — Thousands of Books Online</h3>
        <div className="lib-grid">
          {LIBRARIES.map(l => (
            <div className="lib-item" key={l.name}>
              <h4>{l.name}</h4>
              <p>{l.desc}</p>
              <a href={l.link} target="_blank" rel="noopener noreferrer" className="lib-link">Visit →</a>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

