// ──────────────────────────────────────────────
// ROOT APP
// ──────────────────────────────────────────────
export default function App() {
  const [tab, setTab] = useState("quran");
  const [dark, setDark] = useState(false);
  const [lang, setLang] = useState("en"); // reserved for future i18n
  const [search, setSearch] = useState("");
  const searchRef = useRef(null);

  useEffect(() => {
    document.body.className = dark ? "dark" : "";
  }, [dark]);

  const renderPage = () => {
    switch (tab) {
      case "quran":    return <QuranPage />;
      case "hadith":   return <HadithPage />;
      case "duas":     return <DuasPage />;
      case "pillars":  return <PillarsPage />;
      case "concepts": return <ConceptsPage />;
      case "books":    return <BooksPage search={search} />;
      case "advanced": return <AdvancedPage />;
      case "audio":    return <AudioPage />;
      default:         return <QuranPage />;
    }
  };

  return (
    <>
      {/* Top announcement bar */}
      <div className="topbar">
        Free Islamic Resources &nbsp;|&nbsp;
        <span>Books &gt;17,000</span> •
        <span>Audio &gt;10,000</span> •
        <span>Videos &gt;50,000</span>
        &nbsp;| Always free, always authentic
      </div>

      {/* Sticky header */}
      <header className="header">
        <div className="header-inner">
          <div className="logo">
            <div className="logo-icon">📖</div>
            <div className="logo-text">
              Islamic Knowledge Hub
              <small>Quran · Hadith · Books · Lectures</small>
            </div>
          </div>

          <div className="header-search">
            <Icon name="search" size={16} />
            <input
              ref={searchRef}
              type="text"
              placeholder="Search books, hadith, duas…"
              value={search}
              onChange={e => { setSearch(e.target.value); if (e.target.value) setTab("books"); }}
            />
          </div>

          <div className="header-actions">
            <button className="hbtn" onClick={() => setDark(d => !d)}>
              <Icon name={dark ? "sun" : "moon"} size={15} />
              {dark ? "Light" : "Dark"}
            </button>
            <button className="hbtn gold" onClick={() => setLang(l => l === "en" ? "kin" : "en")}>
              <Icon name="globe" size={15} />
              {lang === "en" ? "Kinyarwanda" : "English"}
            </button>
          </div>
        </div>
      </header>

      {/* Sticky nav tabs */}
      <nav className="nav-bar">
        <div className="nav-inner">
          {TABS.map(t => (
            <button
              key={t.id}
              className={`nav-btn${tab === t.id ? " active" : ""}`}
              onClick={() => { setTab(t.id); setSearch(""); }}
            >
              <Icon name={t.icon} size={16} />
              {t.label}
            </button>
          ))}
        </div>
      </nav>

      {/* Main content */}
      <main className="main">
        {renderPage()}
      </main>

      {/* Footer */}
      <footer className="footer">
        <p>These sources provide authentic Islamic knowledge. Always verify with <strong>qualified scholars</strong>.</p>
        <p>© 2026 <strong>Islamic Knowledge Hub</strong> | Mugisha Is'haq &nbsp;·&nbsp; Built with React</p>
      </footer>
    </>
  );
}
